/**
 * Synchronize the API key owner Peer current state
 *
 * Bearer API key fixes the owner Peer; no Peer selector is accepted. timestamp is the server-issued checkpoint from the last successfully completed sync, or 0 for the first sync. The Server compares current authorized read-API projections against that checkpoint, coalescing each item to its latest full state. Checkpoint hashes are persisted in the Peer KV store; the last 64 checkpoints are retained for at most 24 hours. An unknown or expired timestamp starts with reset and returns all current state. The connection ends after done. Errors occur before SSE starts and use the standard JSON error response. Covers device identity/runtime/status/firmware/runtime-profile/MHS manifest, owned Workspaces, Contacts, Friends, Friend Groups/members, and permitted invite tokens. History, log and telemetry queries, device RPC operations, and API key management retain their existing endpoints. Clients must use the returned timestamp rather than their local clock. Stage each batch and commit state and timestamp together only on done; discard an incomplete batch.
 */
export const syncPeer = <ThrowOnError extends boolean = false>(options: Options<SyncPeerData, ThrowOnError, SyncPeerResponse>): Promise<ServerSentEventsResult<SyncPeerResponses>> => (options.client ?? client).sse.get<SyncPeerResponses, SyncPeerErrors, ThrowOnError>({
    security: [{ scheme: 'bearer', type: 'http' }],
    url: '/gizclaw/v1/sync',
    ...options
});

/**
 * Stream a Lua application package to the API key owner device
 *
 * Single request; no replay. Forward bounded Binary frames to client.lua.app.install. Success means device installation and atomic publication completed. The device owns format-1 lua-app manifest, tar, zlib and file validation. Failures preserve the old application and user data. Maximum 512 KiB and 120 seconds. Larger compressed archives must use the lua.app.install HTTP(S) URL download tool.
 */
export const installLuaApp = <ThrowOnError extends boolean = false>(options: Options<InstallLuaAppData, ThrowOnError>): RequestResult<InstallLuaAppResponses, InstallLuaAppErrors, ThrowOnError> => (options.client ?? client).post<InstallLuaAppResponses, InstallLuaAppErrors, ThrowOnError>({
    bodySerializer: null,
    security: [{ scheme: 'bearer', type: 'http' }],
    url: '/gizclaw/v1/device/lua-app/install',
    ...options,
    headers: {
        'Content-Type': 'application/octet-stream',
        ...options.headers
    }
});
